#!/usr/bin/env python3
"""Generated by stone render. Do not edit: change .cornerstone/config.yaml and render again.

Check K15: fail if the instruction file is over the line limit.
The limit is instruction_file_max_lines in the model profile.
Run it in the repo root. Usage: instruction_size.py [--mode warn|block] [--format text|github]
"""

import argparse
import sys
from pathlib import Path

INSTRUCTION_FILE = "AGENTS.md"  # CLAUDE.md has one line, "@AGENTS.md", so only AGENTS.md counts.
MAX_LINES = 300


def finding() -> str | None:
    path = Path(INSTRUCTION_FILE)
    if not path.is_file():
        return f"{INSTRUCTION_FILE}: no file. Write the instruction file."
    lines = len(path.read_text(encoding="utf-8").splitlines())
    if lines <= MAX_LINES:
        return None
    return (f"{INSTRUCTION_FILE} has {lines} lines. The limit is {MAX_LINES}. Remove each line "
            "whose removal does not cause a mistake. Move facts to the files that own them.")


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description="Check K15: instruction file size.")
    parser.add_argument("--mode", choices=["warn", "block"], default="block")
    parser.add_argument("--format", choices=["text", "github"], default="text")
    args = parser.parse_args(argv)
    message = finding()
    if message and args.format == "github":
        level = "error" if args.mode == "block" else "warning"
        print(f"::{level} file={INSTRUCTION_FILE}::K15: {message}")
    elif message:
        print(f"K15: {message}")
    print(f"K15: {1 if message else 0} finding(s).")
    return 1 if message and args.mode == "block" else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
